$images = Export-OfficeDocumentImage -Path .\Reports\Weekly-Ops.xlsx -Sheet Dashboard -Range A1:H30
$body = foreach ($image in $images) {
    '<img alt="{0}" src="data:image/png;base64,{1}">' -f $image.Name, [Convert]::ToBase64String($image.Bytes)
}
Set-Content -Path .\Reports\Weekly-Ops.html -Value "<html><body>$($body -join '')</body></html>"

$logo = Get-Item -Path .\Brand\Logo.svg | ConvertTo-OfficeVisual -Width 4cm -AlternativeText 'Northwind logo'
New-OfficeWord -Path .\Reports\Brand-Update.docx {
    WordImage -InputObject $logo
    WordHeading 'Brand update'
    WordParagraph 'The refreshed logo is used in every template from 1 November.'
}
New-OfficePowerPoint -Path .\Decks\Brand-Update.pptx {
    PptSlide -Title 'Our new logo' {
        PptImage -InputObject $logo
    }
}
